# Writes .github/workflows/pyre-ci.yml from upstream's CI_build.yml: the same jobs, run only by hand (Actions > Pyre909
# CI > Run workflow, or gh workflow run pyre-ci.yml --ref pyre -f ref=<branch>), on any branch, tag or commit. On the
# fork, upstream's CI_build workflow is disabled (gh workflow disable CI_build), so pushes build nothing.
# Run it again after an upstream merge that changes CI_build.yml. PowerShell 7.
$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '..' '..')).Path
$lines = Get-Content -Path (Join-Path $root '.github/workflows/CI_build.yml') -Encoding utf8

$out = [Collections.Generic.List[string]]::new()
$out.Add('# Generated by .github/pyre/make-ci.ps1 from CI_build.yml: edit that script, not this file.')
for ($i = 0; $i -lt $lines.Count; $i++) {
	$line = $lines[$i]
	if ($line -eq 'name: CI_build') {
		$out.Add('name: Pyre909 CI')
	}
	elseif ($line -eq 'on: [push, pull_request]') {
		$out.Add('on:')
		$out.Add('  workflow_dispatch:')
		$out.Add('    inputs:')
		$out.Add('      ref:')
		$out.Add("        description: 'Branch, tag or commit to build'")
		$out.Add('        required: true')
		$out.Add("        default: 'pyre'")
		$out.Add('      jobs:')
		$out.Add("        description: 'all: every job; auto: as upstream decides from the last commit ([force all], .md only...)'")
		$out.Add('        type: choice')
		$out.Add('        options: [all, auto]')
		$out.Add('        default: all')
		$out.Add('')
		$out.Add('run-name: ${{ inputs.ref }} (${{ inputs.jobs }})')
	}
	elseif ($line -match '^(\s+)uses: actions/checkout@') {
		# every checkout takes the ref asked for
		$indent = $Matches[1]
		$out.Add($line)
		if (($i + 1 -lt $lines.Count) -and ($lines[$i + 1] -eq "${indent}with:")) {
			$out.Add($lines[++$i])
		}
		else {
			$out.Add("${indent}with:")
		}
		$out.Add("${indent}  ref: `${{ inputs.ref }}")
	}
	elseif ($line -match '^(\s+)\$commit_title = ') {
		$out.Add($line)
		$out.Add("$($Matches[1])if (`"`${{ inputs.jobs }}`" -eq `"all`") { `$commit_title = `"[force all] `$commit_title`" }")
	}
	else {
		$out.Add($line)
	}
}

$text = ($out -join "`n") + "`n"
foreach ($expected in 'workflow_dispatch:', 'ref: ${{ inputs.ref }}', '[force all] $commit_title') {
	if (-not $text.Contains($expected)) { throw "CI_build.yml changed: '$expected' not generated, update make-ci.ps1" }
}
$target = Join-Path $root '.github/workflows/pyre-ci.yml'
[IO.File]::WriteAllText($target, $text, [Text.UTF8Encoding]::new($false))
"-> $target"
